366	<body>
367	  <main>
368	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
369	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
370	        <circle cx="200" cy="200" r="200"/>
371	      </svg>
372	    </button>
373	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
374	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
375	    <div class="controls" role="group" aria-label="Circle controls">
376	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
377	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
378	    </div>
379	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
380	  </main>
381	
382	  <script defer>
383	    const CONFIG = {
384	      storageKey: 'circle-state',
385	      tapDelay: 300,
386	      colorShiftDuration: 500,
387	      colorModes: [
388	        { class: 'default', name: 'Default White' },
389	        { class: 'color-mode-1', name: 'Pink' },
390	        { class: 'color-mode-2', name: 'Teal' },
391	        { class: 'color-mode-3', name: 'Mint' }
392	      ],
393	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
394	      pulseInterval: 2500
395	    };
396	
397	    const el = {
398	      circle: document.getElementById('decorative-circle'),
399	      hint: document.getElementById('hint-text'),
400	      modeIndicator: document.getElementById('mode-indicator'),
401	      cycleBtn: document.getElementById('cycle-btn'),
402	      resetBtn: document.getElementById('reset-btn')
403	    };
404	
405	    let state = { active: false, colorMode: 0 };
406	    let tapCount = 0;
407	    let tapTimeout = null;
408	    let animatingColorShift = false;
409	
410	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
411	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
412	
413	    const storage = {
414	      save() {
415	        try {
416	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
417	        } catch {
418	          // Silently fail if localStorage is unavailable or quota exceeded
419	        }
420	      },
421	      load() {
422	        try {
423	          const saved = localStorage.getItem(CONFIG.storageKey);
424	          if (saved) {
425	            const parsed = JSON.parse(saved);
426	            if (parsed && typeof parsed === 'object') {
427	              state = { ...state, ...parsed };
428	            }
429	          }
430	        } catch {
431	          // Silently fail if parsing fails
432	        }
433	      }
434	    };
435	
436	    const updateClasses = () => {
437	      const colorClasses = CONFIG.colorModes.map(m => m.class);
438	      el.circle.classList.remove('active', ...colorClasses);
439	      el.circle.setAttribute('aria-pressed', state.active);
440	      if (state.active) el.circle.classList.add('active');
441	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
442	    };
443	
444	    const updateUI = () => {
445	      let hintText = state.active ? 'Active! ' : '';
446	
447	      if (CONFIG.isTouch) {
448	        hintText += state.active ? 'Tap to cycle colors' : 'Tap once to activate, twice to change color';
449	      } else {
450	        hintText += state.active ? 'Double-click to cycle • Press C or use button' : 'Double-click to change color • Press C or use button';
451	      }
452	
453	      el.hint.textContent = hintText;
454	
455	      const showMode = state.active && state.colorMode > 0;
456	      el.modeIndicator.classList.toggle('visible', showMode);
457	      if (showMode) {
458	        const modeName = getColorModeName(state.colorMode);
459	        el.modeIndicator.textContent = `${modeName.toUpperCase()} MODE`;
460	      }
461	    };
462	
463	    const applyState = () => {
464	      updateClasses();
465	      updateUI();
466	    };
467	
468	    const toggleActive = () => {
469	      state.active = !state.active;
470	      applyState();
471	      storage.save();
472	    };
473	
474	    const cycleColor = () => {
475	      if (animatingColorShift) return;
476	      animatingColorShift = true;
477	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
478	      state.active = true;
479	      el.circle.classList.add('color-shifting');
480	      setTimeout(() => {
481	        el.circle.classList.remove('color-shifting');
482	        animatingColorShift = false;
483	      }, CONFIG.colorShiftDuration);
484	      applyState();
485	      storage.save();
486	    };
487	
488	    const resetState = () => {
489	      state = { active: false, colorMode: 0 };
490	      applyState();
491	      storage.save();
492	    };
493	
494	    const handleDblClick = (e) => {
495	      e.preventDefault();
496	      if (!state.active) {
497	        state.active = true;
498	        applyState();
499	      }
500	      cycleColor();
501	    };
502	
503	    const handleTouchEnd = () => {
504	      tapCount++;
505	      clearTimeout(tapTimeout);
506	      if (tapCount === 1) {
507	        tapTimeout = setTimeout(() => {
508	          if (tapCount === 1) toggleActive();
509	          tapCount = 0;
510	        }, CONFIG.tapDelay);
511	      } else if (tapCount === 2) {
512	        cycleColor();
513	        tapCount = 0;
514	      }
515	    };
516	
517	    const keyHandlers = {
518	      ' ': toggleActive,
519	      'enter': toggleActive,
520	      'c': cycleColor,
521	      'r': resetState
522	    };
523	
524	    const handleKeyDown = (e) => {
525	      const handler = keyHandlers[e.key.toLowerCase()];
526	      if (handler) {
527	        e.preventDefault();
528	        handler();
529	      }
530	    };
531	
532	    const initListeners = () => {
533	      el.circle.addEventListener('click', toggleActive);
534	      el.circle.addEventListener('dblclick', handleDblClick);
535	      el.circle.addEventListener('touchend', handleTouchEnd);
536	      el.circle.addEventListener('blur', () => {
537	        tapCount = 0;
538	        clearTimeout(tapTimeout);
539	      });
540	      document.addEventListener('keydown', handleKeyDown);
541	      el.cycleBtn.addEventListener('click', cycleColor);
542	      el.resetBtn.addEventListener('click', resetState);
543	    };
544	
545	    const initApp = () => {
546	      storage.load();
547	      applyState();
548	      initListeners();
549	      requestAnimationFrame(() => el.circle.focus());
550	    };
551	
552	    if (document.readyState === 'loading') {
553	      document.addEventListener('DOMContentLoaded', initApp);
554	    } else {
555	      initApp();
556	    }
557	  </script>
558	</body>
559	</html>
